seed-b-backend.Api/Controllers/ProductsController.cs    # GetProducts um sortBy/sortDirection-Query-Parameter erweitert
seed-b-backend.Tests/Application/CatalogServiceTests.cs # SeedProductsWithOffers + 6 neue Tests

seed-b-frontend/src/app/features/catalog/catalog-api.service.ts    # getProducts um Sortierparameter erweitert
