using Microsoft.AspNetCore.Mvc;
using seed_b_backend.Api.Application;
using seed_b_backend.Api.Controllers.Dtos;

namespace seed_b_backend.Api.Controllers;

[ApiController]
[Route("api/products")]
public class ProductsController(CatalogService catalogService) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<ProductListResponse>> GetProducts([FromQuery] int page = 1, [FromQuery] string? categoryId = null, [FromQuery] string? subcategoryId = null, [FromQuery] string? sortBy = null, [FromQuery] string? sortDirection = null, CancellationToken ct = default)
    {
        var result = await catalogService.GetProductsAsync(page, categoryId, subcategoryId, sortBy, sortDirection, ct);

        var response = new ProductListResponse
        {
            Items = result.Items.Select(p => new ProductSummaryDto { Id = p.Id, Name = p.Name }).ToList(),
            Page = result.Page,
            PageSize = result.PageSize,
            TotalCount = result.TotalCount
        };

        return Ok(response);
    }
}
